        description = "<p>Parses the <code>value</code> in token format. A token is considered to be one of the following:</p><ul><li>A word surrounded by whitespace.</li><li>Text delimited by double quotes: <code>\"..\"</code>. Quotes can be included in the token if they are escaped by a backslash (<code>\\</code>).</li><li>Text delimited by square brackets: <code>[..]</code>. Closing square brackets can be included in the token if they are escaped by a backslash (<code>\\</code>).</li></ul>",
        isFallible = true,
        isPure = true,
        arguments = listOf(
            VRLFunctionArgument(
                "value",
                setOf("string"),
                "The string to tokenize.",
                true
            )
        ),
        returnTypes = setOf("array", "error"),
        examples = listOf(
            VRLFunctionExample(
                "Parse tokens",
                "parse_tokens(s'A sentence \"with \\\"a\\\" sentence inside\" and [some brackets]')",
                "[\"A\",\"sentence\",\"with \\\\\\\"a\\\\\\\" sentence inside\",\"and\",\"some brackets\"]",
                false
            )
        )
    ),
