    "parse_user_agent" to VRLFunction(
        name = "parse_user_agent",
        description = "<p>Parses the provided <code>value</code> as a user agent, which has <a href=\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/User-Agent\">a loosely defined format</a>.</p>\n\n<p>Parses on the basis of best effort. Returned schema depends only on the configured <code>mode</code>, so if the function fails to parse a field it will set it to <code>null</code>.</p>",
        isFallible = false,
        isPure = true,
        arguments = listOf(
            VRLFunctionArgument(
                "value",
                setOf("string"),
                "The string to parse.",
                true
            ),
            VRLFunctionArgument(
                "mode",
                setOf("string"),
                "Determines performance and reliability characteristics.",
                false,
                defaultValue = "fast"
            )
        ),
        returnTypes = setOf("object"),
        examples = listOf(
            VRLFunctionExample(
                "Fast mode",
                "parse_user_agent(\n    \"Mozilla Firefox 1.0.1 Mozilla/5.0 (X11; U; Linux i686; de-DE; rv:1.7.6) Gecko/20050223 Firefox/1.0.1\"\n)",
                "{\n  \"browser\": {\n    \"family\": \"Firefox\",\n    \"version\": \"1.0.1\"\n  },\n  \"device\": {\n    \"category\": \"pc\"\n  },\n  \"os\": {\n    \"family\": \"Linux\",\n    \"version\": null\n  }\n}",
                false
            ),
            VRLFunctionExample(
                "Reliable mode",
