                "{\n  \"browser\": {\n    \"family\": \"Internet Explorer\",\n    \"version\": \"7.66\"\n  },\n  \"device\": {\n    \"category\": \"pc\"\n  },\n  \"os\": {\n    \"family\": \"Windows XP\",\n    \"version\": \"NT 5.1\"\n  }\n}",
                false
            ),
            VRLFunctionExample(
                "Enriched mode",
